ALTER TABLE public.admin_job_controls ADD COLUMN IF NOT EXISTS priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','urgent'));
CREATE OR REPLACE VIEW public.dispatch_operational_jobs AS
WITH jobs AS (
SELECT 'booking'::text kind,b.id,b.customer_id,b.provider_id assignee_id,b.category,b.address,b.description,b.status::text status,b.price,b.payment_status,b.dispatch_state,b.scheduled_for,b.created_at,b.updated_at,b.completed_at,p.display_name customer_name,p.phone customer_phone,u.email customer_email,pr.business_name assignee_name,b.lat,b.lng FROM public.bookings b LEFT JOIN public.profiles p ON p.user_id=b.customer_id LEFT JOIN auth.users u ON u.id=b.customer_id LEFT JOIN public.providers pr ON pr.id=b.provider_id
UNION ALL SELECT 'delivery',d.id,d.customer_id,d.driver_id,d.service_tier,d.pickup_address||' → '||d.dropoff_address,d.notes,d.status,d.price,d.payment_status,d.dispatch_state,NULL::timestamptz,d.created_at,d.updated_at,d.delivered_at,p.display_name,p.phone,u.email,dr.full_name,d.pickup_lat,d.pickup_lng FROM public.deliveries d LEFT JOIN public.profiles p ON p.user_id=d.customer_id LEFT JOIN auth.users u ON u.id=d.customer_id LEFT JOIN public.driver_profiles dr ON dr.user_id=d.driver_id)
SELECT j.*,coalesce(c.held,false) held,coalesce(c.manual_dispatch,false) manual_dispatch,coalesce(c.priority,'normal') priority,EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=j.customer_id AND ur.role='business') business,EXISTS(SELECT 1 FROM public.admin_job_changes ch WHERE ch.kind=j.kind AND ch.job_id=j.id AND ch.status IN ('pending_customer','pending_assignee')) pending_change,EXISTS(SELECT 1 FROM public.job_offers o WHERE j.kind='booking' AND o.booking_id=j.id AND o.status='offered' AND o.expires_at>now()) OR EXISTS(SELECT 1 FROM public.delivery_offers o WHERE j.kind='delivery' AND o.delivery_id=j.id AND o.status='offered' AND o.expires_at>now()) live_offer FROM jobs j LEFT JOIN public.admin_job_controls c ON c.kind=j.kind AND c.job_id=j.id;
REVOKE ALL ON public.dispatch_operational_jobs FROM PUBLIC,anon,authenticated; GRANT SELECT ON public.dispatch_operational_jobs TO service_role;
CREATE OR REPLACE FUNCTION public.admin_dispatch_directory(_filters jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE result jsonb; BEGIN
IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF;
WITH base AS (SELECT * FROM public.dispatch_operational_jobs j WHERE (coalesce(_filters->>'kind','all')='all' OR j.kind=_filters->>'kind') AND (coalesce(_filters->>'term','')='' OR strpos(lower(concat_ws(' ',j.id,j.customer_id,j.assignee_id,j.address,j.category,j.description,j.customer_name,j.customer_phone,j.customer_email,j.assignee_name)),lower(_filters->>'term'))>0) AND (coalesce(_filters->>'category','')='' OR strpos(lower(j.category),lower(_filters->>'category'))>0) AND (coalesce(_filters->>'customer','')='' OR strpos(lower(concat_ws(' ',j.customer_id,j.customer_name,j.customer_phone,j.customer_email)),lower(_filters->>'customer'))>0) AND (coalesce(_filters->>'assignee','')='' OR strpos(lower(concat_ws(' ',j.assignee_id,j.assignee_name)),lower(_filters->>'assignee'))>0) AND (coalesce(_filters->>'priority','all')='all' OR j.priority=_filters->>'priority') AND (coalesce(_filters->>'business','all')='all' OR j.business) AND (coalesce(_filters->>'from','')='' OR j.created_at>=(nullif(_filters->>'from','')::date::timestamp AT TIME ZONE 'Africa/Harare')) AND (coalesce(_filters->>'to','')='' OR j.created_at<((nullif(_filters->>'to','')::date+1)::timestamp AT TIME ZONE 'Africa/Harare')) AND (coalesce(_filters->>'scheduledFrom','')='' OR j.scheduled_for>=(nullif(_filters->>'scheduledFrom','')::date::timestamp AT TIME ZONE 'Africa/Harare')) AND (coalesce(_filters->>'scheduledTo','')='' OR j.scheduled_for<((nullif(_filters->>'scheduledTo','')::date+1)::timestamp AT TIME ZONE 'Africa/Harare'))),
annotated AS (SELECT j.*,status NOT IN ('completed','delivered','cancelled','refunded','failed') active,assignee_id IS NULL AND status IN ('pending','matching','offered') AND NOT live_offer unassigned,status IN ('pending','matching','offered') AND (live_offer OR assignee_id IS NOT NULL) awaiting,status IN ('picked_up','travelling','provider_arriving','arrived','in_progress') progressing,scheduled_for>now() AND status NOT IN ('completed','delivered','cancelled','refunded','failed') scheduled,scheduled_for<now() AND status NOT IN ('completed','delivered','cancelled','refunded','failed') overdue,held OR pending_change OR status='disputed' OR dispatch_state IN ('no_providers','no_drivers') OR (status='delivered' AND NOT EXISTS(SELECT 1 FROM public.deliveries d WHERE d.id=j.id AND d.proof_photo_url IS NOT NULL)) attention FROM base j),
filtered AS (SELECT * FROM annotated j WHERE CASE coalesce(_filters->>'view','all') WHEN 'all' THEN true WHEN 'active' THEN active WHEN 'unassigned' THEN unassigned WHEN 'awaiting_acceptance' THEN awaiting WHEN 'awaiting_driver' THEN awaiting AND kind='delivery' WHEN 'awaiting_provider' THEN awaiting AND kind='booking' WHEN 'assigned' THEN assignee_id IS NOT NULL AND active WHEN 'accepted' THEN status='accepted' WHEN 'awaiting_collection' THEN status IN ('accepted','arriving','arrived','travelling','provider_arriving') WHEN 'in_transit' THEN progressing WHEN 'scheduled' THEN scheduled WHEN 'delayed' THEN overdue WHEN 'completed' THEN status IN ('completed','delivered') WHEN 'completed_today' THEN completed_at>=(date_trunc('day',now() AT TIME ZONE 'Africa/Harare') AT TIME ZONE 'Africa/Harare') AND status IN ('completed','delivered') WHEN 'failed' THEN status='failed' OR dispatch_state IN ('no_providers','no_drivers') WHEN 'cancelled' THEN status='cancelled' WHEN 'intervention' THEN attention ELSE false END), page AS (SELECT * FROM filtered ORDER BY CASE priority WHEN 'urgent' THEN 0 WHEN 'high' THEN 1 WHEN 'normal' THEN 2 ELSE 3 END,created_at DESC,id DESC OFFSET greatest(0,least(10000,coalesce((_filters->>'page')::integer,0)))*25 LIMIT 25)
SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM page p),'[]'::jsonb),'total',(SELECT count(*) FROM filtered),'metrics',(SELECT jsonb_build_object('active',count(*) FILTER(WHERE active),'unassigned',count(*) FILTER(WHERE unassigned),'awaiting_driver',count(*) FILTER(WHERE awaiting AND kind='delivery'),'awaiting_provider',count(*) FILTER(WHERE awaiting AND kind='booking'),'assigned',count(*) FILTER(WHERE assignee_id IS NOT NULL AND active),'in_transit',count(*) FILTER(WHERE progressing),'scheduled',count(*) FILTER(WHERE scheduled),'delayed',count(*) FILTER(WHERE overdue),'intervention',count(*) FILTER(WHERE attention),'completed_today',count(*) FILTER(WHERE status IN ('completed','delivered') AND completed_at>=(date_trunc('day',now() AT TIME ZONE 'Africa/Harare') AT TIME ZONE 'Africa/Harare')),'failed',count(*) FILTER(WHERE status='failed' OR dispatch_state IN ('no_providers','no_drivers')),'cancelled',count(*) FILTER(WHERE status='cancelled')) FROM annotated),'as_of',now()) INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.admin_dispatch_directory(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_dispatch_directory(jsonb) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.admin_dispatch_priority(_kind text,_id uuid,_expected timestamptz,_key uuid,_priority text,_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE j jsonb; tbl text; before_priority text; replay public.admin_job_actions; BEGIN
IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF;
IF _kind NOT IN ('booking','delivery') OR _priority NOT IN ('low','normal','high','urgent') OR length(trim(_reason))<5 OR length(_reason)>1000 THEN RAISE EXCEPTION 'Valid priority, job type and reason required'; END IF;
tbl:=CASE WHEN _kind='booking' THEN 'bookings' ELSE 'deliveries' END; EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE id=$1 FOR UPDATE',tbl) INTO j USING _id; IF j IS NULL THEN RAISE EXCEPTION 'Job not found'; END IF;
SELECT * INTO replay FROM public.admin_job_actions WHERE action_key=_key; IF FOUND THEN IF replay.actor<>auth.uid() OR replay.kind<>_kind OR replay.job_id<>_id OR replay.action<>'priority' OR replay.after_values->>'priority'<>_priority THEN RAISE EXCEPTION 'Action key already used'; END IF; RETURN jsonb_build_object('ok',true,'idempotent',true); END IF;
IF (j->>'updated_at')::timestamptz IS DISTINCT FROM _expected THEN RAISE EXCEPTION 'This job changed. Refresh before continuing.'; END IF;
IF j->>'status' IN ('completed','delivered','cancelled','failed','refunded') THEN RAISE EXCEPTION 'Terminal job priority cannot change'; END IF;
SELECT coalesce(priority,'normal') INTO before_priority FROM public.admin_job_controls WHERE kind=_kind AND job_id=_id;
INSERT INTO public.admin_job_controls(kind,job_id,priority) VALUES(_kind,_id,_priority) ON CONFLICT(kind,job_id) DO UPDATE SET priority=excluded.priority,updated_at=now(); PERFORM set_config('zwits.trusted','on',true); EXECUTE format('UPDATE public.%I SET updated_at=clock_timestamp() WHERE id=$1',tbl) USING _id;
INSERT INTO public.admin_job_actions(action_key,kind,job_id,actor,action,reason,before_values,after_values) VALUES(_key,_kind,_id,auth.uid(),'priority',_reason,jsonb_build_object('priority',coalesce(before_priority,'normal')),jsonb_build_object('priority',_priority)); PERFORM public.log_admin_action('dispatch_priority',_kind,_id,jsonb_build_object('reason',_reason,'before',coalesce(before_priority,'normal'),'after',_priority)); RETURN jsonb_build_object('ok',true); END $$;
REVOKE ALL ON FUNCTION public.admin_dispatch_priority(text,uuid,timestamptz,uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_dispatch_priority(text,uuid,timestamptz,uuid,text,text) TO authenticated,service_role;